css:
[data-theme="rainbow-light"] .section:nth-of-type(5n+1) .category-icon,
[data-theme="rainbow-light"] .section:nth-of-type(5n+1) .category-name { color: #d83b58; }
[data-theme="rainbow-light"] .section:nth-of-type(5n+2) .category-icon,
[data-theme="rainbow-light"] .section:nth-of-type(5n+2) .category-name { color: #b96b00; }
[data-theme="rainbow-light"] .section:nth-of-type(5n+3) .category-icon,
[data-theme="rainbow-light"] .section:nth-of-type(5n+3) .category-name { color: #218a52; }
[data-theme="rainbow-light"] .section:nth-of-type(5n+4) .category-icon,
[data-theme="rainbow-light"] .section:nth-of-type(5n+4) .category-name { color: #2475b8; }
[data-theme="rainbow-light"] .section:nth-of-type(5n+5) .category-icon,
[data-theme="rainbow-light"] .section:nth-of-type(5n+5) .category-name { color: #8a4db5; }

[data-theme="rainbow-light"] .web-link:nth-child(5n+1) .web-link-icon { color: #d83b58; }
[data-theme="rainbow-light"] .web-link:nth-child(5n+2) .web-link-icon { color: #b96b00; }
[data-theme="rainbow-light"] .web-link:nth-child(5n+3) .web-link-icon { color: #218a52; }
[data-theme="rainbow-light"] .web-link:nth-child(5n+4) .web-link-icon { color: #2475b8; }
[data-theme="rainbow-light"] .web-link:nth-child(5n+5) .web-link-icon { color: #8a4db5; }

[data-theme="rainbow-light"] .service-icon {
  background: #d8e0eb;
  border: 1px solid #bcc7d5;
  border-radius: 6px;
  padding: 4px;
  box-sizing: border-box;
  filter: none !important;
  opacity: 1;
}
[data-theme="rainbow-light"] .service-icon img {
  opacity: 1;
  filter: drop-shadow(0 1px 1px rgba(0,0,0,.55)) drop-shadow(0 0 1px rgba(0,0,0,.35)) !important;
}

[data-theme="rainbow-light"] .top-menu,
[data-theme="rainbow-light"] .top-menu-item,
[data-theme="rainbow-light"] .top-menu-item i,
[data-theme="rainbow-light"] .top-menu-label,
[data-theme="rainbow-light"] .menu-check {
  color: var(--text) !important;
}
[data-theme="rainbow-light"] .top-menu-item:hover {
  color: var(--text) !important;
}

[data-theme="rainbow-light"] .small-icon-btn:not(.delete-btn) {
  color: var(--text) !important;
}
[data-theme="rainbow-light"] .small-icon-btn:not(.delete-btn) i {
  color: var(--text) !important;
}

[data-theme="rainbow-light"] button.delete-btn i {
  color: #ff6b6b !important;
}
[data-theme="rainbow-light"] button.delete-btn:hover i {
  color: #ff8a8a !important;
}
